import{_ as s,C as o,c as r,o as t,a2 as a,b as l,w as i,a as d,G as c,a3 as u}from"./chunks/framework.DkPtUiZm.js";const _=JSON.parse('{"title":"React Native : styles avec Uniwind","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/react-native-et-uniwind.md","filePath":"decisions/react-native-et-uniwind.md","lastUpdated":1793889860000}'),p={name:"decisions/react-native-et-uniwind.md"};function m(v,e,h,f,g,b){const n=o("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="react-native-styles-avec-uniwind" tabindex="-1">React Native : styles avec Uniwind <a class="header-anchor" href="#react-native-styles-avec-uniwind" aria-label="Permalink to &quot;React Native : styles avec Uniwind&quot;">​</a></h1><h2 id="decision-et-etat-actuel" tabindex="-1">Décision et état actuel <a class="header-anchor" href="#decision-et-etat-actuel" aria-label="Permalink to &quot;Décision et état actuel&quot;">​</a></h2><p><code>@sia-ui/react-native</code> utilise <strong>Uniwind</strong> pour les styles. Les valeurs restent issues de <code>@sia-ui/tokens</code> et les comportements partagés de <code>@sia-ui/headless</code>. Le paquet natif fournit le rendu et les adaptations Android/iOS.</p><p>Le premier lot est implémenté et <strong>expérimental</strong> : provider, Text, Button, Input, Card, Modal et Toast, complétés par les champs, FormContainer/FormSection, BottomSheet et Select avec recherche intégrée. La démonstration Expo les réunit. Le <a href="./../guides/react-native.html">guide mobile</a> donne les commandes, la matrice de versions, les APIs et les limites. Les exports Android/iOS/web et les tests de comportement vérifient la compilation et la logique ; les essais sur appareils restent nécessaires avant une adoption en production.</p>',4)),(t(),l(u,null,{default:i(()=>[c(n,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20LR%0A%20%20Tokens%5B%22Tokens%20partag%C3%A9s%22%5D%20--%3E%20Web%5B%22Rendu%20web%22%5D%0A%20%20Tokens%20--%3E%20Styles%5B%22G%C3%A9n%C3%A9ration%20CSS%20Uniwind%22%5D%0A%20%20Styles%20--%3E%20Native%5B%22Prototype%20react-native%22%5D%0A%20%20Headless%5B%22Comportements%20partag%C3%A9s%22%5D%20--%3E%20Native%0A%20%20Native%20--%3E%20Expo%5B%22D%C3%A9monstration%20Expo%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="identite-commune-usage-mobile" tabindex="-1">Identité commune, usage mobile <a class="header-anchor" href="#identite-commune-usage-mobile" aria-label="Permalink to &quot;Identité commune, usage mobile&quot;">​</a></h2><p>Le rendu mobile conserve les palettes sémantiques, la typographie, les formes, la hiérarchie visuelle et les états SIA. Les mêmes tokens produisent les styles web et les classes natives, sans copie manuelle d’une deuxième palette.</p><p>Les adaptations concernent les cibles tactiles (au moins 48 unités pour les boutons), les zones sûres, le clavier logiciel, le défilement et le Retour Android. Les props restent natives : <code>onPress</code>, <code>onChangeText</code>, <code>keyboardType</code> et refs TextInput. Le changement de plateforme ne transforme pas les props DOM en contrat commun. Le provider fournit un thème local clair/sombre/système via <code>ScopedTheme</code>.</p><h2 id="mouvement" tabindex="-1">Mouvement <a class="header-anchor" href="#mouvement" aria-label="Permalink to &quot;Mouvement&quot;">​</a></h2><p>Le premier lot utilise <code>Animated</code> de React Native. Les courbes cubic-bezier et les durées proviennent des tokens partagés ; opacité et transformation utilisent le pilote natif. Les animations couvrent appui, focus, modale et toast. Elles peuvent être interrompues et respectent la préférence système de mouvement réduit, suivie pendant l’utilisation. Une prop peut forcer cette réduction, jamais la désactiver contre le choix système.</p><p>Uniwind fournit les styles ; Animated anime les valeurs. Le glissement de poignée des feuilles utilise PanResponder : suivi en JavaScript, retour Animated. Une dépendance dédiée sera évaluée si les interactions de navigation ou les mesures sur appareils le nécessitent.</p><h2 id="frontieres-et-dependances" tabindex="-1">Frontières et dépendances <a class="header-anchor" href="#frontieres-et-dependances" aria-label="Permalink to &quot;Frontières et dépendances&quot;">​</a></h2><ul><li>Tokens et headless restent indépendants d’Uniwind et du runtime React Native.</li><li>La génération du thème et les classes vivent dans le paquet natif.</li><li>L’application fournit React Native, Uniwind et les zones sûres en dépendances compatibles ; la démo fixe ensemble Expo, React Native, React et Tailwind.</li><li>La démo part du template Expo TypeScript officiel, avec sa licence conservée.</li><li>Le preset NativeWind existant reste un export de tokens distinct ; il ne sert pas de configuration Uniwind et ne devient pas un composant mobile.</li><li>La CLI de copie et le registre web ne distribuent pas encore le catalogue natif.</li></ul><h2 id="validation-restante-et-extension-prevue" tabindex="-1">Validation restante et extension prévue <a class="header-anchor" href="#validation-restante-et-extension-prevue" aria-label="Permalink to &quot;Validation restante et extension prévue&quot;">​</a></h2><p>Avant d’étendre le catalogue, vérifier sur Android et iOS :</p><ol><li>thème système, clair/sombre et changement pendant l’utilisation ;</li><li>saisie, clavier logiciel, chargement et erreurs ;</li><li>Retour Android, découpes d’écran et cibles tactiles ;</li><li>fluidité, interruption et mouvement réduit ;</li><li>VoiceOver/TalkBack, focus à l’ouverture et au retour, texte agrandi et contraste.</li></ol><p><strong>Prévu ensuite :</strong> validation sur appareils et parcours métier. La sélection, les feuilles, la navigation, les gardes de session et les états de page sont implémentés. L’intégration Expo Router reste une entrée optionnelle distincte. Le <a href="./../contribuer/backlog.html">backlog</a> distingue les APIs implémentées de ces travaux restants.</p>',12))])}const A=s(p,[["render",m]]);export{_ as __pageData,A as default};
